<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users','password'=>'required|string|min:12|confirmed']);$u=User::create($d);return response()->json(['user'=>$u,'token'=>$u->createToken('api')->plainTextToken],201);} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))return response()->json(['message'=>'Invalid credentials.'],422);return ['user'=>$u,'token'=>$u->createToken('api')->plainTextToken];} public function logout(Request $r){$r->user()->currentAccessToken()->delete();return response()->noContent();} }
